/** Flat fee added to every premium, regardless of the items insured. */
const PROCESSING_FEE = 5;

/** Base premium of each insurable item type. */
const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

/** Initial assessment surcharge on a customer's first insurance. */
const FIRST_INSURANCE_RATE = 0.1;

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type Step = {
  op: string;
  items: Item[];
};

export type Item = Record<string, unknown>;

export type Result = { premium: number };

export type ScenarioOutcome = { results: Result[] };

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const items = scenario.steps[0].items;
  const policyBasePremium = items.reduce(
    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type as string],
    0,
  );
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
  return {
    results: [
      { premium: policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE },
    ],
  };
};

