import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
  });
  it("a single plain sword → base premium 100 G, plus first insurance 10 G and 5 G fee → 115 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("a single plain amulet → base premium 60 G (+10 % first insurance, +5 G fee) → 71 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("a single plain staff → base premium 80 G (+10 % first insurance, +5 G fee) → 93 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }],
        },
      ],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it("a single plain potion → base premium 40 G (+10 % first insurance, +5 G fee) → 49 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }],
        },
      ],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
  });
  it("a single rune → base premium 25 G (+10 % first insurance, +5 G fee) → 33 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 33 }] });
  });
  it("a single moonstone → base premium 25 G (+10 % first insurance, +5 G fee) → 33 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 33 }] });
  });

  // --- Component blocks of 3 alike ---
  it("2 runes → 50 G base premium", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    };
    // 50 base + 10 % first insurance + 5 G fee = 60 G
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base premium (block applies)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    };
    // 60 base + 10 % first insurance + 5 G fee = 71 G
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    };
    // 100 base + 10 % first insurance + 5 G fee = 115 G
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    };
    // 175 base + 10 % first insurance + 5 G fee = 197.5 → 198 G (rounded up)
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    };
    // 75 base + 10 % first insurance + 5 G fee = 87.5 → 88 G
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    };
    // 120 base + 10 % first insurance + 5 G fee = 137 G
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Premium modifiers in isolation ---
  it.todo("cursed sword adds a 50 % risk surcharge on the item's base premium (100 G → +50 G)");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (+30 G)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (+50 G and +30 G)");
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("each contract after the customer's first receives a 15 % discount");
  it.todo("a 5 G processing fee is added to every premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (item-scoped) → 210 G before further modifiers and fee");
  it.todo("policy-wide modifiers (loyalty, first insurance, follow-up) apply to the policy base premium, the fee is added at the very end");

  // --- Rounding ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claim: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claim: insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (the block discount affects the premium only)");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("two swords insured and both damaged → each damage entry gets its own deductible");

  // --- Error cases ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error, no results");
  it.todo("claim referencing an item not part of the policy (amulet damaged, only a sword insured) → error");
  it.todo("claim referencing an item with an unknown type → error");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  it.todo("claim with a damage entry of amount -200 → error");

  // --- Integration examples ---
  it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
});

