  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("each contract after the customer's first receives a 15 % discount");
  it.todo("a 5 G processing fee is added to every premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (item-scoped) → 210 G before further modifiers and fee");
  it.todo("policy-wide modifiers (loyalty, first insurance, follow-up) apply to the policy base premium, the fee is added at the very end");

  // --- Rounding ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claim: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claim: insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (the block discount affects the premium only)");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("two swords insured and both damaged → each damage entry gets its own deductible");

  // --- Error cases ---
