it("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G", () => {
  const scenario = {
    customer: { yearsWithMHPCO: 3 },
    steps: [
      { op: "quote", items: [] },
      {
        op: "quote",
        items: [
          { type: "sword", material: "steel", enchantment: 7, cursed: true },
        ],
